import React, { useState } from 'react';

function Header() {
  const [isOpen, setIsOpen] = useState(false);

  const toggleMenu = () => {
    setIsOpen(!isOpen);
  };

  return (
    <header className="bg-gray-900 p-4 shadow-xl sticky top-0 z-[999]">
      <nav className="container mx-auto flex justify-between items-center">
        <div className="text-2xl font-extrabold text-blue-400">Manoj Kumar R</div>

        {/* Desktop Menu */}
        <ul className="hidden md:flex space-x-8">
          <li><a href="#home" className="text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Home</a></li>
          <li><a href="#about" className="text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">About</a></li>
          <li><a href="#projects" className="text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Projects</a></li>
          <li><a href="#skills" className="text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Skills</a></li>
          <li><a href="#experience" className="text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Experience</a></li>
          <li><a href="#contact" className="text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Contact</a></li>
        </ul>

        {/* Mobile Menu Button */}
        <div className="md:hidden">
          <button onClick={toggleMenu} className="text-gray-300 hover:text-white focus:outline-none focus:text-white">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16"></path>
            </svg>
          </button>
        </div>
      </nav>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-gray-800 bg-opacity-90 py-4">
          <ul className="flex flex-col items-center space-y-4">
            <li><a href="#home" onClick={toggleMenu} className="block text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Home</a></li>
            <li><a href="#about" onClick={toggleMenu} className="block text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">About</a></li>
            <li><a href="#projects" onClick={toggleMenu} className="block text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Projects</a></li>
            <li><a href="#skills" onClick={toggleMenu} className="block text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Skills</a></li>
            <li><a href="#experience" onClick={toggleMenu} className="block text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Experience</a></li>
            <li><a href="#contact" onClick={toggleMenu} className="block text-gray-300 hover:text-blue-400 transition duration-300 text-lg font-medium">Contact</a></li>
          </ul>
        </div>
      )}
    </header>
  );
}

export default Header;
